def _reward_feet_jerk(self):
        # The original term penalizes contact-force changes, not kinematic jerk.
        forces = self.env.contact_forces[:, self.env.feet_indices, :]
        if not hasattr(self.env, "last_contact_forces"):
            result = torch.zeros(self.env.num_envs, device=self.env.device)
        else:
            result = (forces - self.env.last_contact_forces[..., :3]).norm(dim=-1).sum(dim=-1)
        self.env.last_contact_forces = forces.clone()
        result[self.env.episode_length_buf < 50] = 0.
        return result, result

